(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-715":{scenario:{legacy:"F"},learning:{summary:{vi:"Điều phối viên và giám sát viên nghiên cứu thử nghiệm lâm sàng (CRA) bảo đảm thử nghiệm được thực hiện đúng đề cương, đúng GCP và quy định, quyền lợi và an toàn của người tham gia được bảo vệ, dữ liệu chính xác và kiểm chứng được với hồ sơ nguồn. Người làm nghề khởi động điểm nghiên cứu, giám sát định kỳ, kiểm tra dữ liệu nguồn, theo dõi biến cố bất lợi và quản lý thuốc nghiên cứu.",en:"A clinical research associate (CRA) makes sure a trial follows the protocol, GCP and regulations, that participants' rights and safety are protected and that data are accurate and verifiable against source records. The role initiates sites, runs monitoring visits, performs source data verification, tracks adverse events and oversees investigational product accountability."},responsibilities:{vi:["Đánh giá, khởi động điểm nghiên cứu và đào tạo nhóm nghiên cứu về đề cương, quy trình.","Giám sát định kỳ: kiểm tra phiếu chấp thuận tham gia, tiêu chí lựa chọn và tuân thủ đề cương.","Kiểm tra dữ liệu nguồn (SDV), đặt và theo dõi câu hỏi dữ liệu trên hệ thống EDC.","Theo dõi báo cáo biến cố bất lợi nghiêm trọng đúng hạn và đối chiếu với hồ sơ bệnh án.","Kiểm kê thuốc nghiên cứu, hồ sơ thử nghiệm (TMF) và lập báo cáo giám sát."],en:["Qualify and initiate sites and train study teams on the protocol and procedures.","Run routine monitoring: check informed consent, eligibility and protocol compliance.","Perform source data verification (SDV) and raise and follow data queries in the EDC.","Track timely SAE reporting and reconcile it with medical records.","Reconcile investigational product, review the trial master file (TMF) and write monitoring reports."]},competencies:[{name:{vi:"GCP & đạo đức nghiên cứu",en:"GCP & research ethics"},desc:{vi:"Áp dụng nguyên tắc GCP, bảo vệ quyền, an toàn, sự tự nguyện và bảo mật của người tham gia.",en:"Apply GCP and protect participants' rights, safety, voluntariness and confidentiality."}},{name:{vi:"Kiểm tra dữ liệu nguồn",en:"Source data verification"},desc:{vi:"So khớp dữ liệu trên CRF với hồ sơ nguồn, phát hiện sai lệch và dữ liệu thiếu căn cứ.",en:"Match CRF data with source records and detect discrepancies and unsupported entries."}},{name:{vi:"Theo dõi an toàn",en:"Safety oversight"},desc:{vi:"Nhận diện SAE, SUSAR và bảo đảm báo cáo đúng thời hạn theo quy định.",en:"Recognize SAEs and SUSARs and ensure reporting within regulatory timelines."}},{name:{vi:"Giám sát dựa trên rủi ro",en:"Risk-based monitoring"},desc:{vi:"Tập trung nguồn lực vào dữ liệu, quy trình trọng yếu và tín hiệu rủi ro của từng điểm nghiên cứu.",en:"Focus effort on critical data, processes and each site's risk signals."}},{name:{vi:"Giao tiếp & liêm chính",en:"Communication & integrity"},desc:{vi:"Làm việc tôn trọng với nghiên cứu viên nhưng không chấp nhận ký lùi ngày hay sửa dữ liệu.",en:"Work respectfully with investigators but never accept backdating or altered data."}}],knowledge:{vi:["Hướng dẫn ICH E6 về Thực hành tốt thử nghiệm lâm sàng (GCP), phiên bản R3.","Thông tư 29/2018/TT-BYT quy định về thử thuốc trên lâm sàng tại Việt Nam.","Tuyên bố Helsinki của Hiệp hội Y khoa Thế giới về nguyên tắc đạo đức trong nghiên cứu y học.","ICH E2A về định nghĩa SAE, SUSAR và thời hạn báo cáo nhanh 7 ngày, 15 ngày.","Quy định hiện hành về Hội đồng đạo đức trong nghiên cứu y sinh học và phiếu chấp thuận tham gia.","Nguyên tắc toàn vẹn dữ liệu ALCOA+ áp dụng cho hồ sơ nguồn và dữ liệu điện tử."],en:["ICH E6 Good Clinical Practice (GCP), revision R3.","Circular 29/2018/TT-BYT on clinical trials of medicines in Vietnam.","The World Medical Association Declaration of Helsinki on ethical principles for medical research.","ICH E2A on SAE and SUSAR definitions and the 7-day and 15-day expedited reporting timelines.","Current rules on biomedical research ethics committees and informed consent.","ALCOA+ data integrity principles for source records and electronic data."]},tools:["Hệ thống thu thập dữ liệu điện tử (EDC)","Hệ thống quản lý thử nghiệm (CTMS)","Hồ sơ thử nghiệm điện tử (eTMF)","Hệ thống phân bổ ngẫu nhiên (IRT)","Microsoft Excel"],kpis:{vi:["Tỷ lệ báo cáo giám sát nộp đúng hạn sau mỗi lần giám sát.","Thời gian trung bình đóng câu hỏi dữ liệu trên EDC.","Tỷ lệ SAE được báo cáo trong thời hạn quy định (mục tiêu 100%).","Số phát hiện nghiêm trọng khi thanh tra, đánh giá điểm nghiên cứu (mục tiêu bằng 0)."],en:["Share of monitoring reports submitted on time after each visit.","Average time to close data queries in the EDC.","Share of SAEs reported within the required timeline (target 100%).","Critical findings in site inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Rà soát chỉ số rủi ro, câu hỏi dữ liệu tồn đọng và mục tiêu chuyến giám sát.",en:"Review risk indicators, open queries and the visit objectives."},{time:"09:30",vi:"Kiểm tra phiếu chấp thuận tham gia và tiêu chí lựa chọn của người tham gia mới.",en:"Check consent forms and eligibility of newly enrolled participants."},{time:"11:00",vi:"Kiểm tra dữ liệu nguồn, đối chiếu bệnh án với CRF và đặt câu hỏi dữ liệu.",en:"Perform SDV, match medical records with the CRF and raise queries."},{time:"14:00",vi:"Kiểm kê thuốc nghiên cứu, nhiệt độ bảo quản và hồ sơ tại điểm nghiên cứu.",en:"Reconcile investigational product, storage temperatures and site files."},{time:"16:30",vi:"Họp kết thúc với nghiên cứu viên chính, thống nhất hành động khắc phục.",en:"Hold the close-out meeting with the principal investigator and agree actions."}],mistakes:{vi:["Chỉ kiểm tra dữ liệu trên EDC mà không đối chiếu hồ sơ nguồn gốc.","Bỏ qua việc người tham gia được tuyển trước ngày ký phiếu chấp thuận.","Kết luận dữ liệu đã xác minh khi mới có một nguồn kiểm tra."],en:["Checking EDC data without comparing it to the original source.","Missing that a participant was enrolled before signing consent.","Marking data verified when only one check has been done."]},career:[{vi:"Điều phối viên nghiên cứu tại điểm (CRC)",en:"Clinical research coordinator (CRC)"},{vi:"Giám sát viên nghiên cứu lâm sàng (CRA)",en:"Clinical research associate (CRA)"},{vi:"CRA cấp cao / Trưởng nhóm giám sát",en:"Senior CRA / Lead CRA"},{vi:"Quản lý dự án thử nghiệm lâm sàng",en:"Clinical project manager"}],glossary:[{term:"GCP",vi:"Thực hành tốt thử nghiệm lâm sàng: chuẩn mực đạo đức và khoa học cho thiết kế, thực hiện, ghi nhận và báo cáo thử nghiệm.",en:"Good Clinical Practice: the ethical and scientific standard for designing, conducting, recording and reporting trials."},{term:"SDV",vi:"Kiểm tra dữ liệu nguồn: so khớp dữ liệu trên phiếu thu thập với hồ sơ gốc.",en:"Source data verification: matching case report form data with original records."},{term:"CRF",vi:"Phiếu thu thập dữ liệu ca bệnh theo đề cương, dạng giấy hoặc điện tử.",en:"Case report form collecting protocol data, on paper or electronically."},{term:"SUSAR",vi:"Phản ứng có hại nghiêm trọng, không mong đợi, nghi ngờ do thuốc nghiên cứu, phải báo cáo nhanh.",en:"Suspected unexpected serious adverse reaction requiring expedited reporting."},{term:"Informed consent",vi:"Chấp thuận tham gia tự nguyện sau khi được giải thích đầy đủ, ký trước mọi thủ tục nghiên cứu.",en:"Voluntary agreement after full explanation, signed before any study procedure."}],quiz:[{q:{vi:"Kiểm tra 400 trường dữ liệu, phát hiện 12 trường không khớp hồ sơ nguồn. Tỷ lệ sai lệch là bao nhiêu?",en:"You verify 400 data fields and 12 do not match source. What is the discrepancy rate?"},options:{vi:["0,3%","12%","3%","33%"],en:["0.3%","12%","3%","33%"]},answer:2,explain:{vi:"Tỷ lệ = 12 / 400 = 0,03 = 3%; cần phân tích nguyên nhân nếu vượt ngưỡng của kế hoạch giám sát.",en:"Rate = 12 / 400 = 0.03 = 3%; analyse causes if it exceeds the monitoring plan threshold."}},{q:{vi:"Nghiên cứu viên muốn ký lùi ngày phiếu chấp thuận cho một người tham gia đã được lấy máu. Bạn làm gì?",en:"An investigator wants to backdate a consent form for a participant whose blood was already drawn. What do you do?"},options:{vi:["Từ chối, ghi nhận sai lệch đề cương, báo nhà tài trợ và yêu cầu xử lý theo quy định","Đồng ý vì người tham gia đã đồng ý miệng","Tự sửa ngày trên bản sao","Bỏ qua vì chỉ là thủ tục"],en:["Refuse, log a protocol deviation, inform the sponsor and require proper handling","Agree since verbal consent was given","Fix the date on the copy yourself","Ignore it as paperwork"]},answer:0,explain:{vi:"Chấp thuận phải ký trước mọi thủ tục; ký lùi ngày là làm sai hồ sơ và vi phạm GCP.",en:"Consent must precede any procedure; backdating falsifies records and breaches GCP."}},{q:{vi:"Theo ICH E2A, SUSAR gây tử vong hoặc đe dọa tính mạng phải báo cáo nhanh cho cơ quan quản lý trong bao lâu?",en:"Under ICH E2A, how fast must a fatal or life-threatening SUSAR be reported to regulators?"},options:{vi:["30 ngày","15 ngày","Trong báo cáo năm","7 ngày theo lịch"],en:["30 days","15 days","In the annual report","7 calendar days"]},answer:3,explain:{vi:"SUSAR gây tử vong hoặc đe dọa tính mạng: 7 ngày; các SUSAR khác: 15 ngày.",en:"Fatal or life-threatening SUSARs: 7 days; other SUSARs: 15 days."}},{q:{vi:"Dữ liệu nguồn là gì?",en:"What are source data?"},options:{vi:["Dữ liệu đã nhập vào EDC","Thông tin gốc ghi nhận lần đầu trong bệnh án, phiếu xét nghiệm","Bảng tổng hợp của nhà tài trợ","Báo cáo thống kê cuối cùng"],en:["Data entered in the EDC","Original information first recorded in charts and lab reports","The sponsor's summary tables","The final statistical report"]},answer:1,explain:{vi:"Dữ liệu nguồn là thông tin gốc trong hồ sơ nguồn, cần thiết để tái dựng và đánh giá thử nghiệm.",en:"Source data are the original records needed to reconstruct and evaluate the trial."}}],tools_en:["Electronic data capture (EDC) system","Clinical trial management system (CTMS)","Electronic trial master file (eTMF)","Randomization system (IRT)","Microsoft Excel"]}}})})(window.KKR);
